set-variable.value:
@{
        return new JObject(
            new JProperty("claude-opus-4-8-slurmfactory-eastus2-dz", new JObject(
                new JProperty("EASTUS2", new JObject(
                    new JProperty("url", "{{foundry-eastus2-endpoint}}"),
                    new JProperty("path", "anthropic"),
                    new JProperty("deployment", "claude-opus-4-8-slurmfactory-eastus2-dz"),
                    new JProperty("priority", 1),
                    new JProperty("acceptablePriorities", "1, 2, 3"),
                    new JProperty("timeout", 120),
                    new JProperty("bufferResponse", false),
                    new JProperty("auth", "MI")
                ))
            ))
        );
    }
